AckRisk.query:
mutation AckRisk($riskId: String!, $systemKeys: [SystemKey!]!, $ackBy: String!, $justification: JustificationType!, $comments: String) {
    riskAcknowledge(riskId: $riskId, systemKeys: $systemKeys, acknowledgedBy: $ackBy, riskAcknowledgementFlag: true, justification: $justification, comments: $comments) {
      status message updatedCount
    }
  }

MitigateRisk.query:
mutation MitigateRisk($riskId: String!, $systemKeys: [SystemKey!]!, $mitigationDate: DateTime!, $status: RiskMitigationStatus!, $tool: RiskMitigationTool!, $toolUser: String!) {
    riskMitigation(riskId: $riskId, systemKeys: $systemKeys, mitigationDate: $mitigationDate, status: $status, mitigationTool: $tool, mitigationToolUser: $toolUser) {
      status message
    }
  }

UpdateCQV.query:
mutation UpdateCQV($systemKeys: [SystemKey!]!, $qualifiedVersion: String, $justification: String!) {
    updateQualifiedVersion(systemKeys: $systemKeys, qualifiedVersion: $qualifiedVersion, justification: $justification) {
      status message numberOfSystemsUpdated
    }
  }

CreateCSP.query:
mutation CreateCSP($accountPlan: AccountPlanCreateInput!) {
        createSuccessPlan(accountPlan: $accountPlan) { success id accountId errors }
      }

UpdateCSP.query:
mutation UpdateCSP($nagpId: String!, $accountPlanId: String!, $accountPlan: AccountPlanUpdateInput) {
        updateSuccessPlan(nagpId: $nagpId, accountPlanId: $accountPlanId, accountPlan: $accountPlan) { success results { id type success errors } }
      }

CloseCSP.query:
mutation CloseCSP($nagpId: String!, $accountPlanId: String!, $accountPlan: AccountPlanUpdateInput) {
      updateSuccessPlan(nagpId: $nagpId, accountPlanId: $accountPlanId, accountPlan: $accountPlan) { success results { id type success errors } }
    }

case_summary.query:
